package vn.rtr.aeris.shell29;
import java.util.*;import vn.rtr.aeris.shell24.Json;import vn.rtr.aeris.shell24.VideoModel;
/** Shared native journey. Synthetic observations only; no vehicle/network output. */
public final class Workflow {
 public static final long PREFLIGHT_MAX_AGE=30000;public static final int MAX_EVENTS=256;
 public final String session;public final InputOwner input;public final VideoModel video=new VideoModel();private Plan plan=Catalog.get(0);private long clock=-1,generation=1,revision=1,observation=-1;private boolean connected=true,focused=false,homeConfirmed=false,altitudeConfirmed=false,evidenceComplete=true;private String workspace="Plan",phase="DRAFT",reason="CHOOSE_SURVEY",runId=null,tail="",persistedSha=null,observedSnapshot="null";private int cursor=0;private final List<String> events=new ArrayList<>();
 public Workflow(){this(UUID.randomUUID().toString());}public Workflow(String s){if(s==null||!s.matches("[a-zA-Z0-9:_-]{1,64}"))throw new IllegalArgumentException("Session");session=s;input=new InputOwner(s);}
 public Plan plan(){return plan;}public long generation(){return generation;}public long revision(){return revision;}public int cursor(){return cursor;}public String phase(){return phase;}public String workspace(){return workspace;}public boolean focused(){return focused;}public boolean connectionLive(){return connected;}public boolean evidenceComplete(){return evidenceComplete;}public List<String> events(){return new ArrayList<>(events);}
 private void time(long t){if(t<0||t<clock){invalidate("CLOCK_REGRESSION",Math.max(0,clock));throw new IllegalArgumentException("Monotonic journey clock");}clock=t;input.tick(t);}
 private boolean active(){return phase.equals("RUNNING_MOCK")||phase.equals("UI_SUSPENDED_MOCK")||phase.equals("HOLD_MOCK")||phase.equals("AWAITING_MOCK_LANDING");}
 private void log(String kind,long t){if(events.size()>=MAX_EVENTS){evidenceComplete=false;phase="INTERRUPTED_EVIDENCE_BOUND";reason="JOURNAL_BOUND";input.revoke(t);video.stop("EVIDENCE_BOUND");return;}String body="{\"n\":"+(events.size()+1)+",\"elapsedMs\":"+t+",\"session\":"+Json.quote(session)+",\"generation\":"+generation+",\"revision\":"+revision+",\"planSha256\":"+Json.quote(plan.sha)+",\"runId\":"+Json.quote(runId)+",\"kind\":"+Json.quote(kind)+",\"cursor\":"+cursor+",\"previousSha256\":"+Json.quote(tail)+"}";tail=Plan.hash(body);events.add("{\"body\":"+body+",\"canonicalBody\":"+Json.quote(body)+",\"sha256\":"+Json.quote(tail)+"}");persistedSha=null;}
 private void revokeGates(){observedSnapshot="null";observation=-1;homeConfirmed=altitudeConfirmed=false;}
 private void invalidate(String why,long t){revokeGates();input.revoke(t);video.stop(why);if(active())phase="INTERRUPTED_"+why;reason=why;log(why,t);}
 public void focus(boolean f,long t){time(t);focused=f;input.focus(f,t);if(!f){revokeGates();video.stop("FOCUS_LOST");if(active())phase="UI_SUSPENDED_MOCK";reason="UI_FOCUS_LOST_NOT_AIRCRAFT_HOLD";log("UI_FOCUS_LOST",t);}}
 public void navigate(String view,long t){time(t);if(!Arrays.asList("Plan","Preflight","Fly","Review").contains(view))throw new IllegalArgumentException("Workspace");if(!workspace.equals(view)){input.revoke(t);video.stop("WORKSPACE_CHANGED");}workspace=view;reason="WORKSPACE_"+view;}
 public void select(int index,long t){time(t);if(active())throw new IllegalStateException("Active mock run locks plan");Plan p=Catalog.get(index);if(!p.sha.equals(plan.sha)){plan=p;revision++;revokeGates();input.revoke(t);video.stop("PLAN_CHANGED");phase="DRAFT";cursor=0;runId=null;reason="PLAN_REVISED_RECHECK_REQUIRED";log("PLAN_REVISED",t);}}
 public static final class Observation {
  public String session,planSha,profileSha,readbackSha,world,datum,firmware;public long generation,revision,at;public double lat=Double.NaN,lon=Double.NaN,amsl=Double.NaN;public int system=-1,component=-1,fsGcs=-1,timeout=-1,options=-1,gcsSystem=-1;public boolean synthetic=false,disarmed=false;
 }
 public Observation fixture(long t){Observation o=new Observation();o.session=session;o.planSha=plan.sha;o.readbackSha=plan.sha;o.profileSha="c4f28187ea445df1e5779b099dd90a3c324e38b8710a990c75c314f86125306a";o.generation=generation;o.revision=revision;o.at=t;o.world="aeris-flat-world-v1";o.datum="flat-reference";o.firmware="4.7.1";o.lat=10.854;o.lon=106.807;o.amsl=10;o.system=42;o.component=1;o.fsGcs=1;o.timeout=5;o.options=16;o.gcsSystem=255;o.synthetic=true;o.disarmed=true;return o;}
 public boolean inspect(Observation o,long t){time(t);revokeGates();boolean ok=connected&&o!=null&&o.synthetic&&o.disarmed&&o.at>=0&&o.at<=t&&t-o.at<=PREFLIGHT_MAX_AGE&&session.equals(o.session)&&o.generation==generation&&o.revision==revision&&plan.sha.equals(o.planSha)&&plan.sha.equals(o.readbackSha)&&"c4f28187ea445df1e5779b099dd90a3c324e38b8710a990c75c314f86125306a".equals(o.profileSha)&&"aeris-flat-world-v1".equals(o.world)&&"flat-reference".equals(o.datum)&&"4.7.1".equals(o.firmware)&&o.system==42&&o.component==1&&Double.isFinite(o.lat)&&Double.isFinite(o.lon)&&Double.isFinite(o.amsl)&&Math.abs(o.lat-10.854)<1e-9&&Math.abs(o.lon-106.807)<1e-9&&Math.abs(o.amsl-10)<1e-9&&o.fsGcs==1&&o.timeout==5&&o.options==16&&o.gcsSystem==255;
  if(ok){observedSnapshot="{\"profileSha256\":"+Json.quote(o.profileSha)+",\"session\":"+Json.quote(o.session)+",\"generation\":"+o.generation+",\"revision\":"+o.revision+",\"readbackSha256\":"+Json.quote(o.readbackSha)+",\"firmware\":\"4.7.1\",\"aircraft\":{\"system\":42,\"component\":1},\"home\":{\"lat\":"+o.lat+",\"lon\":"+o.lon+",\"amslM\":"+o.amsl+"},\"datum\":\"flat-reference\",\"parameters\":[{\"name\":\"FS_GCS_ENABLE\",\"value\":1,\"unit\":\"enum\"},{\"name\":\"FS_GCS_TIMEOUT\",\"value\":5,\"unit\":\"s\"},{\"name\":\"FS_OPTIONS\",\"value\":16,\"unit\":\"bitmask\"},{\"name\":\"MAV_GCS_SYSID\",\"value\":255,\"unit\":\"system-id\"}],\"origin\":\"SYNTHETIC_NO_PARAM_READ_OR_WRITE\"}";observation=o.at;reason="MOCK_HOME_PROFILE_READBACK_MATCH";if(!active())phase="PREFLIGHT_PENDING_CONFIRMATIONS";}else{reason="PREFLIGHT_MISMATCH_OR_UNKNOWN";if(active())invalidate("PREFLIGHT_CHANGED",t);else phase="PREFLIGHT_BLOCKED";}log(ok?"MOCK_READONLY_PREFLIGHT_MATCH":"MOCK_PREFLIGHT_REFUSED",t);return ok&&evidenceComplete;
 }
 private boolean observationFresh(long t){return observation>=0&&t>=observation&&t-observation<=PREFLIGHT_MAX_AGE;}
 public boolean confirmHome(long t){time(t);if(!observationFresh(t)||!focused)return false;homeConfirmed=true;log("HOME_EXPLICITLY_CONFIRMED",t);return evidenceComplete;}
 public boolean confirmAltitude(long t){time(t);if(!observationFresh(t)||!focused)return false;altitudeConfirmed=true;log("FLAT_WORLD_ALTITUDE_EXPLICITLY_CONFIRMED",t);return evidenceComplete;}
 public boolean ready(long t){time(t);return connected&&focused&&evidenceComplete&&observationFresh(t)&&homeConfirmed&&altitudeConfirmed;}
 public boolean start(long t){if(!ready(t)||active()||!workspace.equals("Fly"))return false;runId=session+"/"+generation+"/"+revision+"/"+(events.size()+1);phase="RUNNING_MOCK";cursor=0;reason="MOCK_RUN_STARTED";log("MOCK_RUN_STARTED",t);return evidenceComplete;}
 public void ack(long t){time(t);if(!phase.equals("RUNNING_MOCK"))throw new IllegalStateException("No pending mock run");log("MOCK_COMMAND_ACK_ACCEPTED_NOT_EXECUTION",t);}
 public boolean step(long t){time(t);if(!phase.equals("RUNNING_MOCK")||!focused||!evidenceComplete||!workspace.equals("Fly"))return false;cursor++;log("MOCK_ROUTE_POINT_OBSERVED",t);if(evidenceComplete&&cursor==plan.points())phase="AWAITING_MOCK_LANDING";return evidenceComplete;}
 public boolean land(long t){time(t);if(!phase.equals("AWAITING_MOCK_LANDING")||!focused||!evidenceComplete||!workspace.equals("Fly"))return false;phase="COMPLETED_MOCK";reason="MOCK_LANDING_OBSERVED";input.revoke(t);video.stop("MOCK_RUN_ENDED");log("MOCK_LANDING_OBSERVED",t);return evidenceComplete;}
 public boolean hold(long t){time(t);if(!phase.equals("RUNNING_MOCK")||!focused||!workspace.equals("Fly"))return false;phase="HOLD_MOCK";input.revoke(t);reason="OPERATOR_MOCK_HOLD";log("MOCK_HOLD",t);return evidenceComplete;}
 public boolean resume(long t){if(!workspace.equals("Fly")||!ready(t)||!phase.equals("UI_SUSPENDED_MOCK")&&!phase.equals("HOLD_MOCK"))return false;phase=cursor>=plan.points()?"AWAITING_MOCK_LANDING":"RUNNING_MOCK";input.revoke(t);reason="EXPLICIT_MOCK_RESUME";log("EXPLICIT_MOCK_RESUME",t);return evidenceComplete;}
 public void disconnect(long t){time(t);connected=false;invalidate("LINK_LOSS",t);generation++;}
 public void reboot(long t){time(t);connected=false;invalidate("MOCK_AIRCRAFT_REBOOT",t);generation++;}
 public void connect(long t){time(t);connected=true;revokeGates();input.revoke(t);video.stop("NEW_MOCK_CONNECTION");reason="EXPLICIT_CONNECT_RECHECK_NO_RESUME";log(reason,t);}
 public boolean acquire(String target,long t){time(t);if(!connected||!ready(t)||!workspace.equals("Fly")||!evidenceComplete)return false;return input.acquire(target,phase.equals("HOLD_MOCK"),generation,t);}
 public void mockNeutral(long t){time(t);input.focus(focused,t);input.attach(generation,t);input.sample(session,generation,"mock:joystick",0,t);input.sample(session,generation,"mock:joystick",0,t+50);input.sample(session,generation,"mock:joystick",0,t+100);input.hold(true,t+100);clock=t+100;}
 public void saved(String digest){if(digest==null||!digest.equals(Plan.hash(review())))throw new IllegalArgumentException("Persist receipt bound to exact snapshot");persistedSha=digest;}
 public String review(){return "{\"format\":\"aeris-native29-mock-review\",\"version\":1,\"producer\":\"JAVA_SYNTHETIC_JOURNEY\",\"operational\":false,\"transport\":\"NONE\",\"session\":"+Json.quote(session)+",\"workspace\":"+Json.quote(workspace)+",\"phase\":"+Json.quote(phase)+",\"reason\":"+Json.quote(reason)+",\"focused\":"+focused+",\"connectionGeneration\":"+generation+",\"syntheticLinkUp\":"+connected+",\"planRevision\":"+revision+",\"plan\":"+plan.json()+",\"preflight\":{\"origin\":\"SYNTHETIC_READONLY_COMPARISON\",\"observedElapsedMs\":"+observation+",\"homeConfirmed\":"+homeConfirmed+",\"altitudeConfirmed\":"+altitudeConfirmed+",\"freshAtSnapshot\":"+observationFresh(Math.max(clock,0))+",\"snapshot\":"+observedSnapshot+"},\"runId\":"+Json.quote(runId)+",\"cursor\":"+cursor+",\"evidenceComplete\":"+evidenceComplete+",\"eventChainTail\":"+Json.quote(tail)+",\"events\":["+String.join(",",events)+"],\"input\":"+input.json()+",\"video\":"+video.json()+",\"media\":[],\"physicalMediaVerified\":false,\"flightExecutionProven\":false,\"authorityRestorable\":false}";}
}
